<?php require_once __DIR__.'/_base.php'; $title='Find Providers'; include __DIR__.'/../includes/header.php'; ?><div class="dashboard-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><section class="content-area"><?php $where="p.verification_status='Approved' AND p.account_status='Active'";$args=[];$q=post('q');$service=(int)($_GET['service']??0);$min=(float)($_GET['min']??0);$max=(float)($_GET['max']??0);if($q){$where.=' AND (p.name LIKE ? OR p.address LIKE ? OR p.bio LIKE ?)';$args=["%$q%","%$q%","%$q%"];}if($service){$where.=' AND EXISTS(SELECT 1 FROM provider_services ps WHERE ps.provider_id=p.id AND ps.service_id=?)';$args[]=$service;}if($min){$where.=' AND p.charges>=?';$args[]=$min;}if($max){$where.=' AND p.charges<=?';$args[]=$max;}$sql="SELECT p.*,COALESCE(AVG(r.rating),0) rating,COUNT(DISTINCT r.id) reviews,GROUP_CONCAT(DISTINCT s.service_name SEPARATOR ', ') services FROM providers p LEFT JOIN ratings r ON r.provider_id=p.id LEFT JOIN provider_services ps ON ps.provider_id=p.id LEFT JOIN services s ON s.id=ps.service_id WHERE $where GROUP BY p.id ORDER BY rating DESC";$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();$services=$pdo->query("SELECT * FROM services WHERE status='Active' ORDER BY service_name")->fetchAll();?><h2>Find Providers</h2><div class="service-card p-3 mb-4"><form class="row g-2"><div class="col-md-4"><input name="q" class="form-control" placeholder="Name, location..." value="<?=e($q)?>"></div><div class="col-md-3"><select name="service" class="form-select"><option value="0">All services</option><?php foreach($services as $s):?><option value="<?=$s['id']?>" <?=$service==$s['id']?'selected':''?>><?=e($s['service_name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input name="min" type="number" class="form-control" placeholder="Min PKR" value="<?=e($_GET['min']??'')?>"></div><div class="col-md-2"><input name="max" type="number" class="form-control" placeholder="Max PKR" value="<?=e($_GET['max']??'')?>"></div><div class="col-md-1"><button class="btn btn-success w-100">Go</button></div></form></div><div class="row g-4"><?php foreach($rows as $p):?><div class="col-md-6 col-xl-4"><div class="provider-card p-4"><div class="d-flex gap-3 align-items-center"><div class="avatar"><?=e(strtoupper(substr($p['name'],0,1)))?></div><div><h5><?=e($p['name'])?></h5><div class="rating">★ <?=number_format($p['rating'],1)?> (<?=$p['reviews']?>)</div></div></div><p class="small text-secondary mt-3"><?=e($p['services']?:'Services not listed')?></p><p class="mb-1"><b>Experience:</b> <?=e($p['experience'])?></p><p class="mb-1"><b>Charges:</b> PKR <?=number_format($p['charges'],2)?></p><p class="mb-3"><b>Location:</b> <?=e($p['address'])?></p><a class="btn btn-success" href="provider-details.php?id=<?=$p['id']?>">View Profile</a></div></div><?php endforeach;?></div><?php if(!$rows):?><div class="alert alert-info mt-4">No approved providers matched your filters.</div><?php endif;?></section></div><?php include __DIR__.'/../includes/footer.php'; ?>